package ociresources

import (
	"io"
	"net/http"
	"strings"
	"sync"
	"testing"
)

// recordingTransport answers every request with a canned Hub tags page and
// remembers which hosts were called.
type recordingTransport struct {
	mu    sync.Mutex
	hosts []string
}

func (rt *recordingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
	rt.mu.Lock()
	rt.hosts = append(rt.hosts, req.URL.Host)
	rt.mu.Unlock()

	body := `{"results":[{"name":"1.27","last_updated":"2026-01-02T03:04:05Z"}]}`
	return &http.Response{
		StatusCode: http.StatusOK,
		Header:     http.Header{"Content-Type": []string{"application/json"}},
		Body:       io.NopCloser(strings.NewReader(body)),
		Request:    req,
	}, nil
}

func (rt *recordingTransport) calls() []string {
	rt.mu.Lock()
	defer rt.mu.Unlock()
	return append([]string(nil), rt.hosts...)
}

// DEVDESK-297: the tag dates are asked of the Hub API for every spelling of
// the Hub that isDockerHub recognises, not only the two bare hostnames.
func TestHubTagsMetaFollowsIsDockerHub(t *testing.T) {
	tests := []struct {
		name     string
		registry string
		wantHub  bool
	}{
		{"bare docker.io", "docker.io", true},
		{"scheme docker.io", "https://docker.io", true},
		{"scheme registry-1 with slash", "https://registry-1.docker.io/", true},
		{"bare registry-1", "registry-1.docker.io", true},
		{"upper case", "DOCKER.IO", true},
		{"private host", "registry.example.com", false},
		{"nexus path", "https://nexus.example.com/repository/x", false},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			rt := &recordingTransport{}
			previous := ociHTTPClient
			ociHTTPClient = &http.Client{Transport: rt}
			t.Cleanup(func() { ociHTTPClient = previous })

			msg := run(t, loadMultiRegistryTagsMetaCmd(7, "k", tt.registry, "library/nginx")).(MultiRegistryTagsMetaMsg)

			if msg.Err != nil {
				t.Fatalf("Err = %v, want none", msg.Err)
			}
			calls := rt.calls()
			if !tt.wantHub {
				if len(calls) != 0 || msg.Meta != nil {
					t.Errorf("calls = %v, Meta = %v, want no request and an empty answer", calls, msg.Meta)
				}
				return
			}
			if len(calls) != 1 || calls[0] != "hub.docker.com" {
				t.Errorf("calls = %v, want one request to hub.docker.com", calls)
			}
			if _, ok := msg.Meta["1.27"]; !ok {
				t.Errorf("Meta = %v, want the tag 1.27 filled in", msg.Meta)
			}
		})
	}
}
// manager serves the registry under.
//
// A registry URL is written either way in practice — the form does not
// normalize it, `registryAPIURL` explicitly accepts both, and this package's own
// examples write `https://nexus.example.com/repository/docker-group`. Every
// Docker-facing use has to strip it, and none of the three that needed to did
// (D39): a `docker pull` reference carrying `https://` is not a reference at
// all, and a hub alias compared against a scheme-bearing string never matched,
// so images from a Hub configured as `https://docker.io` lost their `library/`
// prefix.
func registryHost(registryURL string) string {
	base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
	for _, scheme := range []string{"https://", "http://"} {
		if len(base) >= len(scheme) && strings.EqualFold(base[:len(scheme)], scheme) {
			return base[len(scheme):]
		}
	}
	return base
}

// isDockerHub reports whether a registry URL names Docker Hub, under either of
// the two spellings and with or without a scheme. Hub is the one registry whose
// references carry no host, so every caller has to recognise it.
func isDockerHub(registryURL string) bool {
	host := registryHost(registryURL)
	return strings.EqualFold(host, "docker.io") || strings.EqualFold(host, "registry-1.docker.io")
}

// multiImageName constructs the full image reference for pull/scan.
//
// A Hub reference carries no host under docker: `docker pull nginx` leaves

var ociHTTPClient = &http.Client{Timeout: 15 * time.Second}

// registryAPIURL converts a user-specified registry URL into a v2 API base URL.
//
// This is the one place that *keeps* a scheme rather than stripping it: an
// explicit `http://` is how a registry on a plain-HTTP port is reached, and
// upgrading it would break that registry rather than fix anything. Everything
// Docker-facing goes through registryHost instead (D39).
func registryAPIURL(registryURL string) string {
	base := strings.TrimSuffix(strings.TrimSpace(registryURL), "/")
	if isDockerHub(base) {
		return "https://registry-1.docker.io"
	}
	lower := strings.ToLower(base)
	if !strings.HasPrefix(lower, "http://") && !strings.HasPrefix(lower, "https://") {
		return "https://" + base
	}
	return base
}

// searchRegistryTagsCmd fetches tags from one registry and returns a MultiRegistryTagsLoadedMsg.
//
// ctx belongs to the browser's lot: the command never cancels it. gen is echoed
// on the message so Update can drop an answer a newer lot or a closed browser left behind.
func searchRegistryTagsCmd(ctx context.Context, gen uint64, entryKey, registryURL, alias, apiURL, repo, username, password string) tea.Cmd {
	return func() tea.Msg {
		tags, err := listRegistryTags(ctx, apiURL, repo, username, password)
		return MultiRegistryTagsLoadedMsg{
			Gen: gen, EntryKey: entryKey, RegistryURL: registryURL, Alias: alias, Repo: repo, Tags: tags, Err: err,
		}
	}
}

// fetchDockerHubTagsMeta fetches last_updated times from the Docker Hub public API.
// Works for public repos (no auth needed). Returns partial results on error.
func fetchDockerHubTagsMeta(namespace, repo string) (map[string]time.Time, error) {
	endpoint := fmt.Sprintf("https://hub.docker.com/v2/repositories/%s/%s/tags?page_size=100&ordering=last_updated", namespace, repo)
	req, err := http.NewRequest("GET", endpoint, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Accept", "application/json")
	resp, err := ociHTTPClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer func() { _ = resp.Body.Close() }()
	if resp.StatusCode != http.StatusOK {
		return nil, fmt.Errorf("hub API returned %d", resp.StatusCode)
	}
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, err
	}
	var result struct {
		Results []struct {
			Name        string `json:"name"`
			LastUpdated string `json:"last_updated"`
		} `json:"results"`
	}
	if err := json.Unmarshal(body, &result); err != nil {
		return nil, err
	}
	meta := make(map[string]time.Time, len(result.Results))
	for _, r := range result.Results {
		if t, err := time.Parse(time.RFC3339Nano, r.LastUpdated); err == nil {
			meta[r.Name] = t
		}
	}
	return meta, nil
}

// loadMultiRegistryTagsMetaCmd fetches tag metadata for one registry in the background.
// For Docker Hub it uses the Hub API; other registries return empty (no error).
func loadMultiRegistryTagsMetaCmd(gen uint64, entryKey, registryURL, repo string) tea.Cmd {
	return func() tea.Msg {
		empty := MultiRegistryTagsMetaMsg{Gen: gen, EntryKey: entryKey, RegistryURL: registryURL, Repo: repo}
		// isDockerHub accepts a scheme, a trailing slash and either Hub host.
		if !isDockerHub(registryURL) {
			return empty
		}
		parts := strings.SplitN(repo, "/", 2)
		if len(parts) != 2 {
			return empty
		}
		meta, err := fetchDockerHubTagsMeta(parts[0], parts[1])
		return MultiRegistryTagsMetaMsg{
			Gen: gen, EntryKey: entryKey, RegistryURL: registryURL, Repo: repo, Meta: meta, Err: err,
		}
	}
}

// pullOneImageCmd pulls a Docker image to the local store, emitting
// RegistryPullStartingMsg before and RegistryPullCompleteMsg after — the pair
// jobs.Start needs to track the run (mirrors scanOneImageCmd).
//
// The pull is verified first (§3.82): deps says how, and a pull its signature
// check blocks comes back as an imagepull.BlockedError.
func pullOneImageCmd(imageName string, deps imagepull.Deps) tea.Cmd {
	// The context the pull runs under, so `K` can stop it (D7). It travels on
	// the starting message, which is the same Update that marks the item
	// running — two steps would leave a window where the row is running and
	// cannot be stopped.
	ctx, cancel := context.WithCancel(context.Background())

	return tea.Sequence(
		func() tea.Msg { return RegistryPullStartingMsg{ImageName: imageName, Cancel: cancel} },
		func() tea.Msg {
			// Releases the context whether the pull was cancelled or ran to the
			// end; the registry drops its copy when the item settles.
			defer cancel()

			check, err := imagepull.Pull(ctx, imageName, deps)
			return RegistryPullCompleteMsg{ImageName: imageName, Err: err, Check: check}
		},
	)
}

// detectRegistryGroupCmd calls the generic registrymgr.DetectGroup to determine
// whether reg is a group repository and enumerate its members.

